import { useProxyWatch, useProxyWatchUpdates, useTranslation } from "@fanfanlo";
import { Box, Typography } from "@mui/material";
import { androidFloatWindowData } from "./data";
import { WindowListItem } from "./WindowListItem";

export function WindowList(){
  const { t } = useTranslation('homepage/components/android-float/window/content');

  // 使用 useProxyWatch 获取响应式的窗口列表数据
  const [windowList] = useProxyWatchUpdates(
    androidFloatWindowData.data.windowData,
    'windowList',
    androidFloatWindowData.data.windowData.windowList
  );
  console.log('WindowList render, windowList:', windowList);
  return (
    <Box>
      <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold' }}>
        {t('WindowList.title')}
      </Typography>
      <Typography sx={{ mb: 2, fontWeight: 'bold' }}>
        {t('WindowList.description')}
      </Typography>

      {windowList && windowList.length > 0 ? (
        <Box>
          {windowList.map((item) => (
            <WindowListItem key={item.tag} item={item} />
          ))}
        </Box>
      ) : (
        <Typography variant="body2" sx={{ color: '#999', textAlign: 'center', py: 3 }}>
          {t('WindowList.empty')}
        </Typography>
      )}
    </Box>
  );
}