import { Log, useTranslation } from '@fanfanlo';
import {
  Box,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Stack,
  Switch,
  TextField,
  Typography,
  Alert,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import { useEffect, useState } from 'react';
import { androidFloatWindowData, isValidContent, isTagExists, IAndroidFloatWindowItem } from './data';
import { openFloatWindow } from './android-window';
import { autoWebViewJs } from '@droid/android';

const fileLog = new Log(false, 'window-list-item')
interface IWindowListItemProps {
  item: IAndroidFloatWindowItem;
  onToggle?: (tag: string, isOpen: boolean) => void;
}

export function WindowListItem({ item, onToggle }: IWindowListItemProps) {
  const uiLog = fileLog.sub(false, 'WindowListItem_ui')
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const [isEditing, setIsEditing] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [editName, setEditName] = useState(item.tag);
  const [editContent, setEditContent] = useState(item.contentUrl);
  const [editWidth, setEditWidth] = useState(item.width);
  const [editHeight, setEditHeight] = useState(item.height);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const refreshIsOpen = () => {
    const fnLog = uiLog.sub(false, 'refreshIsOpen_fn')
    const script = `
    var isOpen = com.fanfanlo.lib.components.floatview.floatwindow.Window.isShow("${androidFloatWindowData.getItemTag(item)}");
    isOpen;`;
    const { javaResultString, errMsg } = autoWebViewJs.callScript<boolean>(script);
    fnLog.log('refreshIsOpen sript=', script, `errMsg=${errMsg} and result string = ${javaResultString}`);
    if (errMsg) {
      fnLog.log('refresh is open err', errMsg);
      return;
    }
    setIsOpen(javaResultString === 'true');
  };
  useEffect(() => {
    const effLog = uiLog.sub(false, 'effect_fn')
    refreshIsOpen();
    const dismissType = androidFloatWindowData.getDismissEventType(item);
    const openedType = androidFloatWindowData.getOpenedEventType(item);
    effLog.log('dismissType =', dismissType);
    effLog.log('openedType=', openedType);
    window.addEventListener(dismissType as any, onDismiss);
    window.addEventListener(openedType as any, onOpened);
    function onDismiss() {
      effLog.log('dismiss')
      setIsOpen(false);
    }
    function onOpened(){
      effLog.log('opened')
      setIsOpen(true)
    }
    return () => {
      effLog.log('remove eventlistener')
      window.removeEventListener(dismissType as any, onDismiss);
      window.removeEventListener(openedType as any, onOpened);
    };
  }, []);
  const validateEditForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!editName.trim()) {
      newErrors.name = t('AddWindow.errorEmptyName');
    } else if (isTagExists(editName.trim(), item.tag)) {
      newErrors.name = t('AddWindow.errorDuplicateName');
    }

    if (!editContent.trim()) {
      newErrors.content = t('AddWindow.errorEmptyContent');
    } else if (!isValidContent(editContent)) {
      newErrors.content = t('AddWindow.errorInvalidContent');
    }

    // 验证宽度
    if (editWidth < 0) {
      newErrors.width = t('AddWindow.errorNegativeWidth');
    }

    // 验证高度
    if (editHeight < 0) {
      newErrors.height = t('AddWindow.errorNegativeHeight');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSaveEdit = () => {
    if (!validateEditForm()) {
      return;
    }

    const itemIndex = androidFloatWindowData.data.windowData.windowList.findIndex(i => i.tag === item.tag);

    if (itemIndex !== -1) {
      const updatedItem = {
        ...androidFloatWindowData.data.windowData.windowList[itemIndex],
        tag: editName.trim(),
        contentUrl: editContent.trim(),
        width: editWidth,
        height: editHeight,
        updatedAt: Date.now(),
      };
      androidFloatWindowData.data.windowData.windowList[itemIndex] = updatedItem;
    }

    setIsEditing(false);
    setErrors({});
  };

  const handleDelete = () => {
    const index = androidFloatWindowData.data.windowData.windowList.findIndex(i => i.tag === item.tag);
    if (index !== -1) {
      androidFloatWindowData.data.windowData.windowList.splice(index, 1);
    }
    setShowDeleteConfirm(false);
  };

  const handleToggle = (checked: boolean) => {
    const fnLog = uiLog.sub(false, 'handleToggle_fn')
    fnLog.log('checked = ', checked)
    setIsOpen(checked);

    if (checked) {
      openFloatWindow(item.contentUrl, androidFloatWindowData.getItemTag(item));
    } else {
      const script = `
      com.fanfanlo.lib.components.floatview.floatwindow.Window.exitById("${androidFloatWindowData.getItemTag(item)}")`;
      fnLog.log('script=', script)
      autoWebViewJs.callScript(script);
    }
    if (onToggle) {
      onToggle(item.tag, checked);
    }
  };

  const contentPreview = editContent.length > 50 ? editContent.substring(0, 50) + '...' : editContent;

  return (
    <>
      <Card sx={{ mb: 1 }}>
        <CardContent>
          <Stack direction="row" spacing={2} alignItems="center">
            {/* 开关 */}
            <Switch checked={isOpen} onChange={e => handleToggle(e.target.checked)} />

            {/* 内容部分 */}
            <Box sx={{ flex: 1, minWidth: 0 }}>
              <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>
                {item.tag}
              </Typography>
              <Typography
                variant="body2"
                sx={{ color: '#666', mt: 0.5, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {contentPreview}
              </Typography>
            </Box>

            {/* 按钮组 */}
            <Stack direction="row" spacing={1}>
              <IconButton
                size="small"
                onClick={() => {
                  setEditName(item.tag);
                  setEditContent(item.contentUrl);
                  setEditWidth(item.width);
                  setEditHeight(item.height);
                  setErrors({});
                  setIsEditing(true);
                }}>
                <EditIcon fontSize="small" />
              </IconButton>
              <IconButton size="small" color="error" onClick={() => setShowDeleteConfirm(true)}>
                <DeleteIcon fontSize="small" />
              </IconButton>
            </Stack>
          </Stack>
        </CardContent>
      </Card>

      {/* 编辑对话框 */}
      <Dialog open={isEditing} onClose={() => setIsEditing(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{t('WindowList.edit')}</DialogTitle>
        <DialogContent sx={{ pt: 2 }}>
          <Stack spacing={2}>
            <TextField
              label={t('AddWindow.nameLabel')}
              value={editName}
              onChange={e => {
                setEditName(e.target.value);
                if (errors.name) {
                  setErrors({ ...errors, name: '' });
                }
              }}
              error={!!errors.name}
              helperText={errors.name || t('AddWindow.nameHelper')}
              fullWidth
              size="small"
              sx={{ mt: '0.7rem' }}
            />
            <TextField
              label="URL / HTML"
              value={editContent}
              onChange={e => {
                setEditContent(e.target.value);
                if (errors.content) {
                  setErrors({ ...errors, content: '' });
                }
              }}
              error={!!errors.content}
              helperText={errors.content || t('AddWindow.contentHelper')}
              multiline
              rows={4}
              fullWidth
              size="small"
            />
            {/* 宽度和高度输入框（并排） */}
            <Stack direction="row" spacing={2}>
              <TextField
                label={t('AddWindow.widthLabel')}
                type="number"
                value={editWidth}
                onChange={e => {
                  const val = Number(e.target.value);
                  setEditWidth(val);
                  if (errors.width) {
                    setErrors({ ...errors, width: '' });
                  }
                }}
                error={!!errors.width}
                helperText={errors.width || t('AddWindow.widthHelper')}
                fullWidth
                size="small"
                inputProps={{ min: 0 }}
              />
              <TextField
                label={t('AddWindow.heightLabel')}
                type="number"
                value={editHeight}
                onChange={e => {
                  const val = Number(e.target.value);
                  setEditHeight(val);
                  if (errors.height) {
                    setErrors({ ...errors, height: '' });
                  }
                }}
                error={!!errors.height}
                helperText={errors.height || t('AddWindow.heightHelper')}
                fullWidth
                size="small"
                inputProps={{ min: 0 }}
              />
            </Stack>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setIsEditing(false)} variant="outlined" color="inherit">
            {t('AddWindow.cancelButton')}
          </Button>
          <Button onClick={handleSaveEdit} variant="contained" color="primary">
            {t('AddWindow.editSaveButton')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* 删除确认对话框 */}
      <Dialog open={showDeleteConfirm} onClose={() => setShowDeleteConfirm(false)}>
        <DialogTitle>{t('WindowList.delete')}</DialogTitle>
        <DialogContent>
          <Alert severity="warning">{t('WindowList.deleteConfirm')}</Alert>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowDeleteConfirm(false)}>{t('WindowList.cancel')}</Button>
          <Button onClick={handleDelete} color="error" variant="contained">
            {t('WindowList.confirm')}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
}
